package dev.balaji.moonrose.logtrain.db

import androidx.room.RoomDatabase
import androidx.sqlite.SQLiteConnection

/**
 * Seeds the exercise catalog when the database is first created. There is no
 * exercise-creation UI yet, and workout logging is unusable with an empty catalog.
 */
internal object ExerciseSeedCallback : RoomDatabase.Callback() {
    override fun onCreate(connection: SQLiteConnection) {
        val now = nowMillis()
        SEED_EXERCISES.forEach { seed ->
            val otherBodyParts = seed.otherBodyParts.joinToString(",")
            connection.prepare(
                "INSERT INTO exercises " +
                    "(name, description, exercise_type, body_part, other_body_parts, equipment, " +
                    "builtin, created_at, updated_at) " +
                    "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
            ).use { statement ->
                statement.bindText(1, seed.name)
                statement.bindText(2, seed.description)
                statement.bindText(3, seed.type)
                statement.bindText(4, seed.bodyPart)
                statement.bindText(5, otherBodyParts)
                statement.bindText(6, seed.equipment)
                statement.bindLong(7, 1L)
                statement.bindLong(8, now)
                statement.bindLong(9, now)
                statement.step()
            }
        }
    }
}

private data class Seed(
    val name: String,
    val description: String,
    val type: String,
    val bodyPart: String,
    val otherBodyParts: List<String>,
    val equipment: String,
)

